Future<String> fetchItem(int id) async {
  await Future.delayed(Duration(milliseconds: 300));
  return 'Item $id';
}

Future<List<String>> fetchAll() async {
  final item1 = await fetchItem(1);
  final item2 = await fetchItem(2);
  final item3 = await fetchItem(3);
  return [item1, item2, item3];
}

