  final items = await fetchAll();
  print(items);
}

Future<String> riskyOperation() async {
  await Future.delayed(Duration(milliseconds: 200));
  throw Exception('Kết nối thất bại');
}

Future<String> safeCall() async {
  try {
    return await riskyOperation();
  } catch (e) {
    return 'Đã bắt lỗi: $e';
  }
}

void main() async {
  final result = await safeCall();
  print(result);
  print('Chương trình vẫn tiếp tục chạy');
}

