exercises.solutionCode:
Future<String> slowFetch(int seconds) async {
  await Future.delayed(Duration(seconds: seconds));
  return 'Data loaded';
}

Future<String> fetchWithTimeout(int seconds) async {
  try {
    return await slowFetch(seconds).timeout(
      Duration(seconds: 2),
    );
  } catch (e) {
    return 'Timeout';
  }
}

void main() async {
  print(await fetchWithTimeout(1));
  print(await fetchWithTimeout(3));
}
